  const [editing, setEditing] = useState<Record<BlankKey, boolean>>(() => {
    const next: Record<BlankKey, boolean> = {};
    Object.keys(initialValues).forEach((k) => {
      next[k] = !initialValues[k].trim();
    });
    return next;
  });
