function ChangePasswordModal({ onClose }: { onClose: () => void }) {
  const [currentPassword, setCurrentPassword] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [confirm, setConfirm] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [done, setDone] = useState(false);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!currentPassword || !newPassword) {
      setError("Please fill in every field.");
      return;
    }
    if (newPassword.length < 8) {
      setError("New password must be at least 8 characters.");
      return;
    }
    if (newPassword !== confirm) {
      setError("New password and confirmation don't match.");
      return;
    }
    setError(null);
    setBusy(true);
    try {
      const res = await fetch("/api/auth/me/password", {
        method: "POST",
        credentials: "include",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ currentPassword, newPassword }),
      });
      if (!res.ok) {
        const data = await res.json().catch(() => ({}) as { error?: string });
        setError(
          data.error ?? `Couldn't change password (HTTP ${res.status}).`,
        );
        setBusy(false);
        return;
      }
      // Success — server killed the session. Force a hard reload so we
      // land back on the sign-in screen with the new password.
      setDone(true);
      setTimeout(() => {
        window.location.reload();
      }, 1400);
    } catch {
      setError("Network error — please try again.");
      setBusy(false);
    }
  }

  return (
    <div
      style={{
        position: "fixed",
        inset: 0,
        background: "rgba(0,0,0,0.75)",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        zIndex: 9999,
        padding: 24,
      }}
    >
      <form
        onSubmit={handleSubmit}
        className="fade-up"
        style={{
          width: "100%",
          maxWidth: 440,
          background: "#1a2940",
          border: "1px solid rgba(201,168,76,0.3)",
          borderRadius: 8,
          padding: 32,
          fontFamily: "var(--sans)",
        }}
      >
        <h2
          style={{
            fontFamily: "var(--serif)",
            fontSize: 26,
            fontWeight: 300,
            color: "#e8e3d8",
            marginBottom: 8,
            letterSpacing: "-0.3px",
            lineHeight: 1.25,
          }}
        >
          Change password
        </h2>
        <p
          style={{
            fontSize: 13,
            color: "var(--text3)",
            lineHeight: 1.7,
            marginBottom: 22,
          }}
        >
          You'll be signed out and asked to sign in again with your new
          password.
        </p>
        {done ? (
          <div
            style={{
              fontSize: 13,
              color: "#34d399",
              padding: "12px 14px",
              background: "rgba(52,211,153,0.08)",
              border: "1px solid rgba(52,211,153,0.25)",
              borderRadius: 6,
            }}
          >
            Password updated. Reloading…
          </div>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: 11 }}>
            <label>
              <div
                className="lbl"
                style={{ marginBottom: 6, fontSize: 11, color: "var(--text3)" }}
              >
                Current password
              </div>
              <input
                type="password"
                autoComplete="current-password"
                className="to-field"
                value={currentPassword}
                onChange={(e) => setCurrentPassword(e.target.value)}
                disabled={busy}
                autoFocus
              />
            </label>
            <label>
              <div
                className="lbl"
                style={{ marginBottom: 6, fontSize: 11, color: "var(--text3)" }}
              >
                New password
              </div>
              <input
                type="password"
                autoComplete="new-password"
                className="to-field"
                value={newPassword}
                onChange={(e) => setNewPassword(e.target.value)}
                disabled={busy}
                placeholder="At least 8 characters"
              />
            </label>
            <label>
              <div
                className="lbl"
                style={{ marginBottom: 6, fontSize: 11, color: "var(--text3)" }}
              >
                Confirm new password
              </div>
              <input
                type="password"
                autoComplete="new-password"
                className="to-field"
                value={confirm}
                onChange={(e) => setConfirm(e.target.value)}
                disabled={busy}
              />
            </label>
            {error && (
              <div
                style={{
                  fontSize: 12,
                  color: "#ef4444",
                  background: "rgba(239,68,68,0.08)",
                  border: "1px solid rgba(239,68,68,0.25)",
                  borderRadius: 6,
                  padding: "9px 12px",
                }}
              >
                {error}
              </div>
            )}
            <div style={{ display: "flex", gap: 10, marginTop: 10 }}>
              <button
                type="submit"
                className="btn"
                disabled={busy}
                style={{ flex: 1, justifyContent: "center" }}
              >
                {busy ? "Saving…" : "Save"}
              </button>
              <button
                type="button"
                className="btn-g"
                disabled={busy}
                onClick={onClose}
              >
                Cancel
              </button>
            </div>
          </div>
        )}
      </form>
    </div>
  );
}

function detectMigrationCandidates(serverCache: Record<string, any>): string[] {
  const out: string[] = [];
  const map: Array<[string, string]> = [
    ["map", "to_map"],
    ["voice", "to_voice"],
    ["mapofme_origin", "to_mapofme_origin"],
    ["intake", "to_intake"],
    ["phase", "to_phase"],
    ["step", "to_step"],
    ["done", "to_done"],
  ];
  for (const [serverKey, localKey] of map) {
    const local = localStorage.getItem(localKey);
    if (!local) continue;
    const serverVal = serverCache[serverKey];
    const serverHasReal = serverKey in serverCache && serverVal != null;
    if (!serverHasReal) out.push(serverKey);
  }
  return out;
}

function MigrationModal({ onClose }: { onClose: () => void }) {
  const [busy, setBusy] = useState(false);
  const [candidates] = useState<string[]>(() =>
    detectMigrationCandidates(serverDataCache || {}),
  );

  async function importAll() {
    setBusy(true);
    await Promise.all(
      candidates.map(async (sk) => {
        const localKey = "to_" + sk;
        const raw = localStorage.getItem(localKey);
        if (raw === null) return;
        let value: any = raw;
        try {
          value = JSON.parse(raw);
        } catch {}
        try {
          const r = await fetch(`/api/userdata/${sk}`, {
            method: "PUT",
            credentials: "include",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ value }),
          });
          if (r.ok && serverDataCache) serverDataCache[sk] = value;
        } catch {
          /* swallow */
        }
      }),
    );
    localStorage.setItem("to_migrated", "true");
    setBusy(false);
    onClose();
  }

  function skip() {
    localStorage.setItem("to_migrated", "true");
    onClose();
  }

  return (
    <div
      style={{
        position: "fixed",
        inset: 0,
        background: "rgba(0,0,0,0.75)",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        zIndex: 9999,
        padding: 24,
      }}
    >
      <div
        className="fade-up"
        style={{
          background: "#1a2940",
          border: "1px solid rgba(201,168,76,0.3)",
          borderRadius: 8,
          padding: 36,
          maxWidth: 480,
          fontFamily: "var(--sans)",
        }}
      >
        <h2
          style={{
            fontFamily: "var(--serif)",
            fontSize: 26,
            fontWeight: 300,
            color: "#e8e3d8",
            marginBottom: 16,
            letterSpacing: "-0.3px",
            lineHeight: 1.25,
          }}
        >
          Import your existing work?
        </h2>
        <p
          style={{
            fontSize: 14,
            color: "#a8a497",
            lineHeight: 1.7,
            marginBottom: 28,
          }}
        >
          We found work you've already done in this app on this device. Import
          it to your account so you can pick up where you left off — even from a
          different device.
        </p>
        <button
          className="btn"
          disabled={busy}
          onClick={importAll}
          style={{ marginRight: 10, marginBottom: 10 }}
        >
          {busy ? "Importing…" : "Import to my account"}
        </button>
        <button className="btn-g" disabled={busy} onClick={skip}>
          Skip — start fresh
        </button>
      </div>
    </div>
  );
}

